// Получаем данные из предыдущего узла
const inputData = msg.payload; 

// Создаем массив для демонстрации
let processedValues = [];

// Проверяем, пришел ли объект с массивом
if (inputData && inputData.values) {
    // Используем цикл for для перебора массива
    for (let i = 0; i < inputData.values.length; i++) {
        let currentValue = inputData.values[i];

        // Условие if/else: если число больше 15, умножаем на 2
        if (currentValue > 15) {
            processedValues.push(currentValue * 2);
        } else {
            processedValues.push(currentValue);
        }
    }
} else {
    // Если пришло что-то другое
    processedValues.push("Данные не распознаны");
}

// Создаем новый объект для возврата
const resultObject = {
    student: "Помас",
    originalInput: inputData,
    processed: processedValues,
    timestamp: new Date().toISOString()
};

// Возвращаем объект с полем payload
msg.payload = resultObject;
return msg;
